const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const near=(v,t,d)=>Math.abs(v-t)<=d;

export class OokPulseExtractor {
  constructor({sampleRate=1_024_000,decimation=8,hysteresis=0.12,minPulseUs=40,maxGapUs=30_000}={}){this.configure({sampleRate,decimation,hysteresis,minPulseUs,maxGapUs});}
  configure(o={}){this.sampleRate=Number(o.sampleRate??this.sampleRate??1_024_000);this.decimation=Math.max(1,Math.round(o.decimation??this.decimation??8));this.hysteresis=Number(o.hysteresis??this.hysteresis??0.12);this.minPulseUs=Number(o.minPulseUs??this.minPulseUs??40);this.maxGapUs=Number(o.maxGapUs??this.maxGapUs??30_000);this.usPerSample=1e6*this.decimation/this.sampleRate;this.reset();}
  reset(){this.low=0.002;this.high=0.02;this.level=false;this.durationUs=0;this.acc=0;this.accN=0;this.transitions=0;}
  process(i,q,onPulse){for(let n=0;n<i.length;n++){this.acc+=i[n]*i[n]+q[n]*q[n];this.accN++;if(this.accN<this.decimation)continue;const mag=this.acc/this.accN;this.acc=0;this.accN=0;const threshold=(this.low+this.high)/2;const h=Math.max(1e-6,threshold*this.hysteresis);let next=this.level;if(this.level){if(mag<threshold-h)next=false;else this.high+=0.02*(mag-this.high);}else{if(mag>threshold+h)next=true;else{this.low+=0.01*(mag-this.low);this.high=Math.max(this.high,this.low*1.7);}}this.durationUs+=this.usPerSample;if(next!==this.level||this.durationUs>=this.maxGapUs){if(this.durationUs>=this.minPulseUs)onPulse?.({level:this.level,durationUs:this.durationUs});this.transitions++;this.level=next;this.durationUs=this.usPerSample;}}}
}

export class NexusWeatherDecoder {
 constructor(){this.reset();}
 reset(){this.step=0;this.lastHigh=0;this.bits=[];this.frames=0;}
 feed(level,durationUs){const out=[];const short=490,delta=150,sync=short*8;if(this.step===0){if(!level&&near(durationUs,sync,delta*4)){this.step=1;this.bits=[];}return out;}if(this.step===1){if(level){this.lastHigh=durationUs;this.step=2;}else this.step=0;return out;}if(this.step===2){if(level){this.step=0;return out;}if(near(durationUs,sync,delta*4)){if(this.bits.length===36){const f=this.decode(this.bits);if(f)out.push(f);}this.bits=[];this.step=1;return out;}if(near(this.lastHigh,short,delta)&&near(durationUs,short*2,delta*2))this.bits.push(0);else if(near(this.lastHigh,short,delta)&&near(durationUs,short*4,delta*4))this.bits.push(1);else{this.step=0;this.bits=[];return out;}this.step=1;}return out;}
 decode(bits){let data=0n;for(const b of bits)data=(data<<1n)|BigInt(b);if(Number((data>>8n)&0xfn)!==0xf)return null;const id=Number((data>>28n)&0xffn),batteryLow=!Boolean(Number((data>>27n)&1n)),channel=Number((data>>24n)&3n)+1,neg=Boolean(Number((data>>23n)&1n));let raw=Number((data>>12n)&0x7ffn);let temperatureC=neg?-(((~raw)&0x7ff)+1)/10:raw/10;let humidity=clamp(Number(data&0xffn),20,95);this.frames++;return{family:'weather',protocol:'NexusTH',id:id.toString(16).padStart(2,'0').toUpperCase(),temperatureC,humidity,channel,batteryLow,rawHex:data.toString(16).padStart(9,'0').toUpperCase()};}
}

function bitsToInt(bits,start,count){let v=0;for(let i=0;i<count;i++)v=(v<<1)|(bits[start+i]||0);return v>>>0;}
function manchesterDecode(bits){const out=[];for(let i=0;i+1<bits.length;i+=2){const a=bits[i],b=bits[i+1];if(a===0&&b===1)out.push(0);else if(a===1&&b===0)out.push(1);else return null;}return out;}
export function decodeTpmsSchraderOok8192(bits){if(bits.length<74)return null;const data=manchesterDecode(bits.slice(0,74));if(!data||data.length<37)return null;const flags=bitsToInt(data,0,3),id=bitsToInt(data,3,24),pressureRaw=bitsToInt(data,27,8),checksum=bitsToInt(data,35,2);let sum=data[0];for(let i=1;i<37;i+=2)sum+=bitsToInt(data,i,2);if((sum&3)!==3)return null;return{family:'tpms',protocol:'Schrader OOK 8192',id:id.toString(16).padStart(6,'0').toUpperCase(),pressureKpa:Math.round(pressureRaw*4/3),temperatureC:null,flags:((flags<<4)|checksum).toString(16).padStart(2,'0').toUpperCase()};}
export function decodeTpmsGmcOok8400(bits){if(bits.length<152)return null;const data=manchesterDecode(bits.slice(0,152));if(!data||data.length<76)return null;const id=bitsToInt(data,20,32),p=bitsToInt(data,52,8),t=bitsToInt(data,60,8),crc=bitsToInt(data,68,8);let sum=(4<<4)|bitsToInt(data,0,4);for(let i=4;i<68;i+=8)sum=(sum+bitsToInt(data,i,8))&255;if(sum!==crc)return null;return{family:'tpms',protocol:'GMC_96 OOK 8400',id:id.toString(16).padStart(8,'0').toUpperCase(),pressureKpa:Math.round(p*11/4),temperatureC:t-61,flags:null};}

export class TpmsOokDecoder {
 constructor(){this.reset();}
 reset(){this.bits=[];this.frames=0;this.last=null;}
 feed(level,durationUs){const out=[];if(!level)return out; // timing encoded by high pulses in our normalized fixture/probe
 const unit=durationUs<180?122:durationUs<360?238:null;if(unit==null){this.bits=[];return out;}this.bits.push(unit===238?1:0);if(this.bits.length>=152){const a=decodeTpmsGmcOok8400(this.bits.slice(-152));if(a){this.frames++;out.push(a);this.bits=[];}}if(this.bits.length>=74){const a=decodeTpmsSchraderOok8192(this.bits.slice(-74));if(a){this.frames++;out.push(a);this.bits=[];}}return out;}
}

export class SubGhzTelemetryDecoder {
 constructor({sampleRate=1_024_000,mode='weather'}={}){this.extractor=new OokPulseExtractor({sampleRate});this.weather=new NexusWeatherDecoder();this.tpms=new TpmsOokDecoder();this.pulses=0;this.events=0;this.configure({sampleRate,mode});}
 configure({sampleRate=this.sampleRate,mode=this.mode}={}){const changed=Number(sampleRate)!==this.sampleRate;this.sampleRate=Number(sampleRate);this.mode=mode||'weather';if(changed)this.extractor.configure({sampleRate:this.sampleRate});}
 reset(){this.extractor.reset();this.weather.reset();this.tpms.reset();this.pulses=0;this.events=0;}
 process(i,q,{receivedAtMs=Date.now()}={}){const out=[];this.extractor.process(i,q,(pulse)=>{this.pulses++;const events=this.mode==='tpms'?this.tpms.feed(pulse.level,pulse.durationUs):this.weather.feed(pulse.level,pulse.durationUs);for(const e of events){this.events++;out.push({...e,receivedAtMs});}});return out;}
 snapshot(){return{mode:this.mode,pulses:this.pulses||0,events:this.events||0,transitions:this.extractor.transitions||0,weatherFrames:this.weather.frames||0,tpmsFrames:this.tpms.frames||0};}
}

export function generateNexusWeatherPulses({id=0x42,temperatureC=21.7,humidity=55,channel=1,batteryLow=false}={}){let raw=Math.round(Math.abs(temperatureC)*10)&0x7ff;let data=(BigInt(id&255)<<28n)|(BigInt(batteryLow?0:1)<<27n)|(BigInt((channel-1)&3)<<24n)|(BigInt(temperatureC<0?1:0)<<23n)|(BigInt(raw)<<12n)|(0xfn<<8n)|BigInt(humidity&255);const bits=[];for(let n=35;n>=0;n--)bits.push(Number((data>>BigInt(n))&1n));const p=[{level:false,durationUs:3920}];for(const b of bits)p.push({level:true,durationUs:490},{level:false,durationUs:b?1960:980});p.push({level:true,durationUs:490},{level:false,durationUs:3920},{level:true,durationUs:490});return{pulses:p,expected:{id:id.toString(16).padStart(2,'0').toUpperCase(),temperatureC,humidity,channel,batteryLow}};}
export function renderOokPulsesToIq(pulses,{sampleRate=1_024_000,amplitude=.75,noise=.01}={}){const total=Math.ceil(pulses.reduce((s,p)=>s+p.durationUs,0)*sampleRate/1e6);const i=new Float32Array(total),q=new Float32Array(total);let n=0,seed=1;for(const p of pulses){const count=Math.max(1,Math.round(p.durationUs*sampleRate/1e6));for(let k=0;k<count&&n<total;k++,n++){seed=(seed*1664525+1013904223)>>>0;const r=((seed>>>8)/0xFFFFFF-.5)*noise;i[n]=(p.level?amplitude:0)+r;q[n]=r*.5;}}return{i,q};}
export function generateTpmsSchraderOokPulses({id=0xABCDEF,pressureRaw=180,flags=3}={}){const data=[];for(let n=2;n>=0;n--)data.push((flags>>n)&1);for(let n=23;n>=0;n--)data.push((id>>n)&1);for(let n=7;n>=0;n--)data.push((pressureRaw>>n)&1);let checksum=0;checksum+=data[0];for(let i=1;i<35;i+=2)checksum+=((data[i]<<1)|(data[i+1]||0));const cs=(3-(checksum&3))&3;data.push((cs>>1)&1,cs&1);const enc=[];for(const b of data)enc.push(b?1:0,b?0:1);const pulses=[];for(const b of enc)pulses.push({level:true,durationUs:b?238:122},{level:false,durationUs:122});return{pulses,expected:{id:id.toString(16).padStart(6,'0').toUpperCase(),pressureKpa:Math.round(pressureRaw*4/3)}};}
